#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int n;
    if (scanf("%d", &n) != 1 || n <= 0)
        return 1;
    int *t = malloc(n * sizeof *t);
    if (t == NULL)
        return 1;
    for (int i = 0; i < n; i++)
        t[i] = i * i;
    for (int i = 0; i < n; i++)
        printf("%d ", t[i]);
    printf("\n");
    free(t);
    return 0;
}

